from datetime import date, timedelta

class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # (employee, year) -> days used
        self._used: dict[tuple[str, int], int] = {}

    def _is_leave_day(self, day: date) -> bool:
        # Weekday: 0=Monday ... 6=Sunday
        if day.weekday() >= 5:
            return False
        if day in self.holidays:
            return False
        return True

    def _count_leave_days(self, start: date, end: date) -> int:
        if end < start:
            raise ValueError("end date must not be before start date")
        count = 0
        day = start
        while day <= end:
            if self._is_leave_day(day):
                count += 1
            day += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("end date must not be before start date")
        # Reject if requested less than 3 days before start date
        if (start - today).days < 3:
            raise ValueError("leave must be requested at least 3 days in advance")

        days = self._count_leave_days(start, end)

        # A request spanning multiple years: charge days to the year of each day
        # We'll compute per-year counts to check remaining correctly.
        per_year: dict[int, int] = {}
        day = start
        while day <= end:
            if self._is_leave_day(day):
                per_year[day.year] = per_year.get(day.year, 0) + 1
            day += timedelta(days=1)

        # Check remaining for each affected year
        for year, cnt in per_year.items():
            if cnt > self.remaining(employee, year):
                raise ValueError(
                    f"insufficient leave days for year {year}: "
                    f"requested {cnt}, remaining {self.remaining(employee, year)}"
                )

        # Commit
        for year, cnt in per_year.items():
            key = (employee, year)
            self._used[key] = self._used.get(key, 0) + cnt

        return days

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get((employee, year), 0)
        return max(self.days_per_year - used, 0)
